const AS_TABS = [["over", "Umumiy"], ["rent", "Ijara"], ["amb", "Ambassadorlar"], ["bonus", "Bonuslar"], ["events", "Tadbirlar"], ["corp", "Korporativ"], ["ai", "Mezbon AI"]];
