MODALS.saEvent = m => {
  const e = EV(m.id), c = CLI(e.clientId), os = (e.orders || []).map(ORD).filter(Boolean), bs = (e.bookings || []).map(RB).filter(Boolean), yes = (e.guestList || []).filter(g => g.rsvp === "yes").reduce((a, g) => a + g.count, 0);
  const tot = os.reduce((a, o) => a + (o.vendorId ? orderValue(o) : 0), 0) + bs.filter(b => b.status !== "rad").reduce((a, b) => a + rbTotal(b), 0);
  return mHead(esc(e.title), `${fDateY(e.date)} ${esc(e.time || "")} · ${esc(e.venue || "")} · ${e.guests} kishi`) + `<div class="m-body">
    <div class="live">${money("Mijoz", esc(c ? c.name : "—"))}${money("Jami buyurtmalar", som(tot))}${money("RSVP", yes ? `${yes} kishi kelyapti` : "—")}${money("Checklist", `${(e.checklist || []).filter(x => x.done).length} / ${(e.checklist || []).length}`)}</div>
    <div class="g g-2"><div><span class="lbl">Catering</span><ul class="dots small">${os.map(o => `<li><button type="button" class="link" data-act="open-order" data-id="${o.id}">${o.id}</button> · ${esc(vName(o.vendorId || (o.requests[0] || {}).vendorId))} · ${pill(ORD_ST, o.status)}</li>`).join("") || "<li>—</li>"}</ul></div><div><span class="lbl">Ijara va xizmatlar</span><ul class="dots small">${bs.map(b => `<li>${b.id} · ${esc(vName(b.vendorId))} · ${pill(RB_ST, b.status)}</li>`).join("") || "<li>—</li>"}</ul></div></div>
    <span class="lbl">Tadbir kuni (jonli)</span>${(e.live || []).length ? `<ul class="feed">${e.live.slice().sort((a, b) => b.at - a.at).map(liveRow).join("")}</ul>` : `<p class="small faint">Hali holat yo‘q.</p>`}
    ${e.share ? `<p class="small muted">Mijozga ulashish sahifasi: ${e.share.status === "approved" ? `<span class="pill t-good">mijoz tasdiqladi</span>` : `<span class="pill t-saffron">tasdiq kutilmoqda</span>`}</p>` : ""}
  </div><footer class="m-foot"><button type="button" class="btn btn-primary" data-act="close">Yopish</button></footer>`;
};
function saCorp() {
  const cs = db.clients.filter(c => clType(c) === "company"), mk = today().slice(0, 7), subs = db.subs || [];
  const spend = c => db.orders.filter(o => o.clientId === c.id && o.vendorId && o.date.slice(0, 7) === mk).reduce((a, o) => a + orderValue(o), 0);
  return `<section class="card"><div class="card-h"><h2>Kompaniyalar</h2><span class="small muted">bir nechta xodim buyurtma beradi, oy oxirida bitta hisob-faktura</span></div><div class="tbl"><table><thead><tr><th>Kompaniya</th><th class="r">Xodimlar</th><th class="r">Oylik limit</th><th class="r">Bu oy</th><th>Obunalar</th><th></th></tr></thead><tbody>${cs.map(c => { const sp = spend(c), lim = c.company.budget || 0; return `<tr><td><strong>${esc(c.company.name)}</strong><small>${esc(c.name)} · INN ${esc(c.company.inn || "—")}</small></td><td class="num r">${(c.company.members || []).length}</td><td class="num r">${lim ? mln(lim) : "—"}</td><td class="num r ${lim && sp > lim ? "bad-t" : ""}">${mln(sp)}${lim ? `<small>${pct(sp / lim)}</small>` : ""}</td><td>${subs.filter(s => s.clientId === c.id).map(s => `${esc(vName(s.vendorId))} · ${s.guests} kishi · ${s.status === "active" ? (s.accepted ? "faol" : "tasdiq kutmoqda") : "to‘xtatilgan"}`).join("<br>") || "—"}</td><td><button type="button" class="btn btn-sm" data-act="sa-inv-new" data-id="${c.id}">Hisob-faktura</button></td></tr>`; }).join("") || `<tr><td colspan="6">${empty("Kompaniya yo‘q")}</td></tr>`}</tbody></table></div></section>
  <section class="card"><div class="card-h"><h2>Hisob-fakturalar</h2></div>${(db.invoices || []).length ? `<div class="tbl"><table><thead><tr><th>Raqam</th><th>Kompaniya</th><th>Oy</th><th class="r">Buyurtmalar</th><th class="r">Summa</th><th>Holat</th></tr></thead><tbody>${db.invoices.slice().sort((a, b) => b.month.localeCompare(a.month)).map(x => `<tr><td class="mono">${esc(x.id)}</td><td>${esc(CLI(x.clientId) && CLI(x.clientId).company ? CLI(x.clientId).company.name : "—")}</td><td>${mLabel(x.month)}</td><td class="num r">${x.orders}</td><td class="num r">${som(x.amount)}</td><td>${x.status === "paid" ? `<span class="pill t-good">To‘langan</span>` : `<span class="pill t-saffron">Kutilmoqda</span>`}</td></tr>`).join("")}</tbody></table></div>` : `<p class="small faint">Hali hisob-faktura yo‘q.</p>`}</section>`;
}
function saAI() {
  const ch = (db.aiChats || []).slice().sort((a, b) => b.at - a.at), OUT = { cart: ["Savatga o‘tdi", "good"], rfq: ["Taklif so‘radi", "accent"], handoff: ["Menejerga uzatildi", "saffron"] };
  return `<div class="g g-kpi">${kpi("Suhbatlar", ch.length)}${kpi("Savatga o‘tdi", ch.filter(x => x.outcome === "cart").length)}${kpi("Taklif so‘radi", ch.filter(x => x.outcome === "rfq").length)}${kpi("Menejerga uzatildi", ch.filter(x => x.outcome === "handoff").length)}</div>
  <div class="note info">${ic("globe", 16)}<span>Mezbon hozir demo rejimida ishlaydi: savollarga javob beradi, set tavsiya qiladi, buyurtmani to‘ldirib beradi. Haqiqiy AI (Claude) keyin <span class="mono">js/config.js</span> dagi bitta sozlama bilan ulanadi.</span></div>
  <section class="card"><div class="card-h"><h2>Suhbatlar</h2></div>${ch.length ? `<div class="tbl"><table><thead><tr><th>Vaqt</th><th>Mijoz</th><th>Til</th><th>Birinchi savol</th><th>Natija</th></tr></thead><tbody>${ch.map(x => { const first = (x.msgs.find(mm => mm.from === "user") || {}).text || ""; return `<tr class="click" data-act="sa-ai-open" data-id="${x.id}"><td class="num">${fDT(x.at)}</td><td>${esc(CLI(x.clientId) ? CLI(x.clientId).name : "Mehmon")}</td><td class="mono">${esc(x.lang || "uz")}</td><td>${esc(first.slice(0, 80))}${first.length > 80 ? "…" : ""}</td><td>${x.outcome ? pill(OUT, x.outcome) : `<span class="pill t-neutral">Savol-javob</span>`}</td></tr>`; }).join("")}</tbody></table></div>` : `<p class="small faint">Hali suhbat yo‘q.</p>`}</section>`;
}
MODALS.saAI = m => { const x = (db.aiChats || []).find(c => c.id === m.id); return mHead("Mezbon AI suhbati", `${fDT(x.at)} · ${esc(CLI(x.clientId) ? CLI(x.clientId).name : "Mehmon")}`) + `<div class="m-body"><div class="chat">${x.msgs.map(mm => `<div class="bub ${mm.from === "bot" ? "me" : ""}"><span class="tiny faint">${mm.from === "bot" ? "Mezbon" : "Mijoz"}</span><p class="small">${esc(mm.text)}</p></div>`).join("")}</div></div><footer class="m-foot"><button type="button" class="btn btn-primary" data-act="close">Yopish</button></footer>`; };

